import com.hbm.world.biome.*;import com.hbm.world.feature.*;import net.minecraft.world.*;import net.minecraft.world.biome.*;import net.minecraft.world.gen.feature.*;import net.minecraft.util.math.*;import net.minecraft.block.state.*;import net.minecraft.init.*;import net.minecraft.entity.*;import net.minecraftforge.common.*;import net.minecraftforge.fml.common.registry.*;import net.minecraftforge.fml.common.eventhandler.*;import net.minecraftforge.event.terraingen.*;import java.util.*;import java.lang.reflect.*;
public class NoMansLandNativeTest {
 static int n;static void check(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 static sun.misc.Unsafe unsafe()throws Exception{Field f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);return (sun.misc.Unsafe)f.get(null);}
 static IBlockState terrain(BlockPos p){if(p.getY()<0||p.getY()>255)return Blocks.AIR.getDefaultState();int k=Math.floorMod(p.getX()+p.getY()+p.getZ(),4);return (k==0?Blocks.DIRT:k==1?Blocks.GRASS:k==2?Blocks.STONE:Blocks.WATER).getDefaultState();}
 static String point(BlockPos p){return p.getX()+","+p.getY()+","+p.getZ();}
 static class W extends World {
  List<String> writes,queries;Map<BlockPos,IBlockState> changed;boolean water;W(){super(null,null,null,null,false);}protected net.minecraft.world.chunk.IChunkProvider createChunkProvider(){return null;}protected boolean isChunkLoaded(int x,int z,boolean empty){return true;}
  public IBlockState getBlockState(BlockPos p){if(water){queries.add(point(p));return Blocks.AIR.getDefaultState();}IBlockState state=changed.get(p);return state!=null?state:terrain(p);}
  public boolean setBlockState(BlockPos p,IBlockState s,int flags){writes.add(point(p)+":"+flags+":"+s.getBlock().getMetaFromState(s));changed.put(p.toImmutable(),s);return true;}
  public BlockPos getTopSolidOrLiquidBlock(BlockPos p){return new BlockPos(p.getX(),64+Math.floorMod(p.getX()-p.getZ(),3),p.getZ());}
  public BlockPos getHeight(BlockPos p){return new BlockPos(p.getX(),70,p.getZ());}
 }
 static W world()throws Exception{W w=(W)unsafe().allocateInstance(W.class);w.writes=new ArrayList<>();w.queries=new ArrayList<>();w.changed=new HashMap<>();return w;}
 static List<String> originalSpot(long seed,int radius,float chance,BlockPos center){Random rand=new Random(seed);int r=rand.nextInt(radius-2)+2;List<String> result=new ArrayList<>();for(int x=center.getX()-r;x<=center.getX()+r;x++)for(int z=center.getZ()-r;z<=center.getZ()+r;z++)if((x-center.getX())*(x-center.getX())+(z-center.getZ())*(z-center.getZ())<=r*r)for(int y=center.getY()-2;y<=center.getY()+2;y++){BlockPos p=new BlockPos(x,y,z);net.minecraft.block.Block block=terrain(p).getBlock();if((block==Blocks.DIRT||block==Blocks.GRASS)&&rand.nextFloat()<chance)result.add(point(p)+":2:0");}result.add("rng="+rand.nextLong());return result;}
 static class RecordingGen extends WorldGenerator {String name;List<String> calls;RecordingGen(String name,List<String> calls){this.name=name;this.calls=calls;}public boolean generate(World w,Random r,BlockPos p){calls.add(name+":"+point(p));return true;}}
 static class Dec extends BiomeDecoratorNoMansLand {List<String> calls=new ArrayList<>();Dec(){sandGen=new RecordingGen("sand",calls);((BiomeDecorator)this).gravelGen=new RecordingGen("watergravel",calls);sellafiteGen=new RecordingGen("sellafite",calls);gravelGen=new RecordingGen("customgravel",calls);treesPerChunk=-999;grassPerChunk=0;deadBushPerChunk=0;}protected void generateOres(World w,Random r){calls.add("ores");}void run(Biome b,W w,long seed,BlockPos p){chunkPos=p;Random r=new Random(seed);genDecorations(b,w,r);calls.add("rng="+r.nextLong());}}
 public static class Events {int deny;List<String> types=new ArrayList<>();int pre,post;@SubscribeEvent public void event(DecorateBiomeEvent.Decorate e){types.add(e.getType().name());if(e.getType()==DecorateBiomeEvent.Decorate.EventType.SAND&&(deny&1)!=0||e.getType()==DecorateBiomeEvent.Decorate.EventType.SAND_PASS2&&(deny&2)!=0||e.getType()==DecorateBiomeEvent.Decorate.EventType.LAKE_WATER&&(deny&4)!=0)e.setResult(Event.Result.DENY);}@SubscribeEvent public void pre(DecorateBiomeEvent.Pre e){pre++;}@SubscribeEvent public void post(DecorateBiomeEvent.Post e){post++;}}
 public static void main(String[] args)throws Exception{Bootstrap.register();BiomeGenNoMansLand b=(BiomeGenNoMansLand)BiomeGenNoMansLand.noMansLand;check(!ForgeRegistries.BIOMES.containsKey(b.getRegistryName()),"class load does not activate dormant biome");check(b.getBiomeName().equals("No Man's Land")&&b.getBaseHeight()==.125F&&b.getHeightVariation()==.05F&&b.getWaterColor()==0x6F6F12,"original biome properties");check(b.getGrassColorAtPos(BlockPos.ORIGIN)==0x696F59&&b.getFoliageColorAtPos(BlockPos.ORIGIN)==0x767C67&&b.getSkyColorByTemp(0)==0x949494,"fixed colors");for(EnumCreatureType type:EnumCreatureType.values()){List<Biome.SpawnListEntry> list=b.getSpawnableList(type);check(list.size()==(type==EnumCreatureType.MONSTER?1:0),"original spawn category");if(!list.isEmpty()){Biome.SpawnListEntry e=list.get(0);check(e.minGroupCount==4&&e.maxGroupCount==6&&e.itemWeight==1&&e.entityClass==com.hbm.entity.mob.EntityUndeadSoldier.class,"original hostile spawn tuple");}}check(b.decorator.treesPerChunk==-999&&b.decorator.flowersPerChunk==0&&b.decorator.grassPerChunk==0,"original suppressed decorations");
  for(int seed=0;seed<20;seed++)for(int radius:new int[]{3,6,8})for(float chance:new float[]{0,.15F,1})for(int y:new int[]{0,64,255}){W w=world();BlockPos p=new BlockPos(-17,y,31);Random r=new Random(seed);new WorldGenSurfaceSpot(Blocks.COBBLESTONE,radius,chance).generate(w,r,p);List<String> expected=originalSpot(seed,radius,chance,p);w.writes.add("rng="+r.nextLong());check(w.writes.equals(expected),"original custom spot write sequence/count/RNG "+seed+"/"+radius+"/"+chance+"/"+y);for(IBlockState changed:w.changed.values())check(changed==Blocks.COBBLESTONE.getDefaultState(),"target meta0 state");}
  Events events=new Events();MinecraftForge.EVENT_BUS.register(events);MinecraftForge.TERRAIN_GEN_BUS.register(events);
  try{for(int mask=0;mask<8;mask++)for(int seed=0;seed<8;seed++){events.deny=mask;events.types.clear();int pre=events.pre,post=events.post;Dec d=new Dec();W w=world();w.water=true;BlockPos p=new BlockPos(-32,0,48);d.run(b,w,seed,p);Random r=new Random(seed);List<String> expected=new ArrayList<>();expected.add("ores");String[] names={"sand","watergravel","sellafite","customgravel"};int[] counts={(mask&1)==0?d.sandPatchesPerChunk:0,(mask&2)==0?d.gravelPatchesPerChunk:0,2,2};for(int group=0;group<4;group++)for(int i=0;i<counts[group];i++){int x=p.getX()+r.nextInt(16)+8,z=p.getZ()+r.nextInt(16)+8;expected.add(names[group]+":"+point(w.getTopSolidOrLiquidBlock(new BlockPos(x,0,z))));}r.nextInt(10);List<String> water=new ArrayList<>();if((mask&4)==0&&d.generateFalls)for(int i=0;i<50;i++){int x=p.getX()+r.nextInt(16)+8,y=r.nextInt(r.nextInt(248)+8),z=p.getZ()+r.nextInt(16)+8;water.add(point(new BlockPos(x,y+1,z)));}expected.add("rng="+r.nextLong());check(d.calls.equals(expected),"original configured decoration dispatch/RNG");check(w.queries.equals(water),"50 original water placements and native early-rejection boundary");check(events.types.equals(Arrays.asList("SAND","SAND_PASS2","TREE","GRASS","DEAD_BUSH","LAKE_WATER")),"original terrain event order");check(events.pre==pre+1&&events.post==post+1,"original explicit main-bus Pre/Post");}}
  finally{MinecraftForge.EVENT_BUS.unregister(events);MinecraftForge.TERRAIN_GEN_BUS.unregister(events);}
  BiomeGenNoMansLand.initDictionary();check(ForgeRegistries.BIOMES.getValue(b.getRegistryName())==b,"explicit native registry-phase activation hook");check(BiomeManager.getBiomes(BiomeManager.BiomeType.WARM).stream().anyMatch(e -> e.biome==b && e.itemWeight==5),"original warm-biome weight5");check(BiomeDictionary.hasType(b,BiomeDictionary.Type.DEAD)&&BiomeDictionary.hasType(b,BiomeDictionary.Type.PLAINS)&&BiomeDictionary.hasType(b,BiomeDictionary.Type.WASTELAND),"original tags");System.out.println("PASS "+n+" whole native dormant-biome/decorator/surface-spot checks; generic vanilla ore/worldgen internals and full world generation are not original-parity certified.");
 }
}
